const isItemInEditState = ArasModules.item.isEditState('Form', options.itemId);
if (!isItemInEditState) {
	return { hidden: true };
}

const { commandFactory } = options;
const itemNode = window.item;
const saveCommand = commandFactory('SaveItem', { itemNode });
const state = options.getState();

const isViewOriginal = window.formEditorLayout?.state.isViewOriginalFormMode ? true : false;

const disabled = state.isInvalidForm || !saveCommand.canExecute() || isViewOriginal;
return {
	hidden: false,
	disabled
};
